// ============================================================================
// VoiceLink SAPI Bridge — Class Factory (Implementation)
// ============================================================================
//
// This is a textbook COM class factory. Its only real method is
// CreateInstance(), which does: new VoiceLinkEngine() → QueryInterface().
//
// Everything else (IUnknown, LockServer) is standard boilerplate that
// every COM DLL implements identically.
// ============================================================================

#include "class_factory.h"
#include "tts_engine.h"
#include "debug.h"

// ============================================================================
// Constructor / Destructor
// ============================================================================

VoiceLinkClassFactory::VoiceLinkClassFactory()
    : m_refCount(1)
{
    VLOG(L"VoiceLinkClassFactory created");
}

VoiceLinkClassFactory::~VoiceLinkClassFactory()
{
    VLOG(L"VoiceLinkClassFactory destroyed");
}

// ============================================================================
// IUnknown Implementation
// ============================================================================

STDMETHODIMP VoiceLinkClassFactory::QueryInterface(REFIID riid, void **ppv)
{
    if (!ppv)
        return E_POINTER;
    *ppv = nullptr;

    // We support IUnknown and IClassFactory
    if (riid == IID_IUnknown || riid == IID_IClassFactory)
    {
        *ppv = static_cast<IClassFactory *>(this);
        AddRef();
        return S_OK;
    }

    return E_NOINTERFACE;
}

STDMETHODIMP_(ULONG)
VoiceLinkClassFactory::AddRef()
{
    return InterlockedIncrement(&m_refCount);
}

STDMETHODIMP_(ULONG)
VoiceLinkClassFactory::Release()
{
    LONG count = InterlockedDecrement(&m_refCount);
    if (count == 0)
    {
        delete this;
    }
    return static_cast<ULONG>(count);
}

// ============================================================================
// IClassFactory Implementation
// ============================================================================

STDMETHODIMP VoiceLinkClassFactory::CreateInstance(
    IUnknown *pUnkOuter,
    REFIID riid,
    void **ppv)
{
    // COM aggregation is an advanced feature where one object can appear
    // to be part of another object. We don't support it.
    // If pUnkOuter is non-null, the caller is trying to aggregate us.
    if (pUnkOuter != nullptr)
    {
        return CLASS_E_NOAGGREGATION;
    }

    if (!ppv)
        return E_POINTER;
    *ppv = nullptr;

    // Create the engine object
    // The constructor sets ref count to 1
    auto *engine = new (std::nothrow) VoiceLinkEngine();
    if (!engine)
    {
        VERR(L"Failed to allocate VoiceLinkEngine");
        return E_OUTOFMEMORY;
    }

    // Ask the engine for the interface the caller wants.
    // This also AddRef's the returned interface pointer.
    HRESULT hr = engine->QueryInterface(riid, ppv);

    // Release our initial reference. If QI succeeded, the object survives
    // (ref count goes from 2 back to 1). If QI failed, this destroys it
    // (ref count goes from 1 to 0).
    engine->Release();

    if (FAILED(hr))
    {
        VERR(L"VoiceLinkEngine doesn't support requested interface");
    }
    else
    {
        VLOG(L"VoiceLinkEngine instance created successfully");
    }

    return hr;
}

STDMETHODIMP VoiceLinkClassFactory::LockServer(BOOL fLock)
{
    // LockServer prevents COM from unloading our DLL.
    // Some apps lock the server to keep the DLL loaded for fast
    // subsequent object creation.
    if (fLock)
    {
        InterlockedIncrement(&g_lockCount);
    }
    else
    {
        InterlockedDecrement(&g_lockCount);
    }
    return S_OK;
}

// ============================================================================
// VoiceLink SAPI Bridge — Class Factory (Header)
// ============================================================================
//
// In COM, you never directly "new" an object from outside the DLL.
// Instead, COM asks the DLL for a "class factory" that knows how to
// create objects.
//
// The flow:
//   1. App calls CoCreateInstance(CLSID_VoiceLinkEngine, ...)
//   2. COM calls our DllGetClassObject(CLSID_VoiceLinkEngine, IID_IClassFactory, ...)
//   3. DllGetClassObject creates a VoiceLinkClassFactory and returns it
//   4. COM calls factory->CreateInstance(nullptr, IID_ISpTTSEngine, ...)
//   5. The factory creates a VoiceLinkEngine and returns it
//   6. COM releases the factory (it's no longer needed)
//
// WHY THIS INDIRECTION?
//   - Separation of concerns: creation logic is separate from the object itself
//   - COM can ask for different types of factories in the future
//   - The factory can implement pooling, caching, or other creation strategies
//   - Standard COM pattern — every COM DLL does it this way
//
// In practice, our factory is extremely simple: it just does "new VoiceLinkEngine".
// But the pattern must be followed for COM compatibility.
// ============================================================================

#pragma once

#include <windows.h>
#include <unknwn.h>

// Global counters (defined in dllmain.cpp)
extern LONG g_lockCount;

class VoiceLinkClassFactory : public IClassFactory
{
public:
    VoiceLinkClassFactory();
    ~VoiceLinkClassFactory();

    // -----------------------------------------------------------------------
    // IUnknown — Same as VoiceLinkEngine (every COM object needs these)
    // -----------------------------------------------------------------------
    STDMETHODIMP QueryInterface(REFIID riid, void **ppv) override;
    STDMETHODIMP_(ULONG)
    AddRef() override;
    STDMETHODIMP_(ULONG)
    Release() override;

    // -----------------------------------------------------------------------
    // IClassFactory — The factory interface
    // -----------------------------------------------------------------------

    // Create an instance of VoiceLinkEngine.
    //
    // Parameters:
    //   pUnkOuter — For COM aggregation (we don't support it, must be nullptr)
    //   riid      — The interface the caller wants (usually IID_ISpTTSEngine)
    //   ppv       — Output: pointer to the newly created object
    //
    // This is essentially: *ppv = new VoiceLinkEngine() with QI for riid.
    STDMETHODIMP CreateInstance(IUnknown *pUnkOuter, REFIID riid, void **ppv) override;

    // Lock or unlock the DLL in memory.
    //
    // When fLock is TRUE, increment a global lock count.
    // When FALSE, decrement it.
    // DllCanUnloadNow returns S_OK only when both lock count AND object count are 0.
    //
    // This prevents COM from unloading our DLL while a factory exists,
    // even if all objects have been Released.
    STDMETHODIMP LockServer(BOOL fLock) override;

private:
    LONG m_refCount;
};

// ============================================================================
// VoiceLink SAPI Bridge — Debug / Logging Helpers
// ============================================================================
//
// COM DLLs run inside another process's address space (Thorium Reader,
// Edge, Narrator, etc.). You can't just printf() to see what's happening.
//
// These macros use OutputDebugString, which sends text to:
//   - Visual Studio's Output window (when debugging)
//   - Sysinternals DebugView (free tool, great for production debugging)
//   - Any debugger attached to the host process
//
// WHY NOT A LOGGING LIBRARY?
//   We want zero dependencies. OutputDebugString is built into Windows
//   and adds zero overhead when no debugger is attached (the call becomes
//   a no-op in the kernel).
//
// USAGE:
//   VLOG(L"Speak() called with %d characters", textLen);
//   VERR(L"HTTP request failed: %lu", GetLastError());
//
// In Release builds, you can disable logging by defining VOICELINK_NO_LOG.
// ============================================================================

#pragma once

#include <windows.h>
#include <cstdio>

// Prefix all our messages so they're easy to filter in DebugView
#define VOICELINK_LOG_PREFIX L"[VoiceLink] "

#ifndef VOICELINK_NO_LOG

// General info log
#define VLOG(fmt, ...)                                               \
    do                                                               \
    {                                                                \
        wchar_t _vl_buf[1024];                                       \
        _snwprintf_s(_vl_buf, _countof(_vl_buf), _TRUNCATE,          \
                     VOICELINK_LOG_PREFIX fmt L"\n", ##__VA_ARGS__); \
        OutputDebugStringW(_vl_buf);                                 \
    } while (0)

// Error log (same output, different prefix for easy grep)
#define VERR(fmt, ...)                                          \
    do                                                          \
    {                                                           \
        wchar_t _vl_buf[1024];                                  \
        _snwprintf_s(_vl_buf, _countof(_vl_buf), _TRUNCATE,     \
                     VOICELINK_LOG_PREFIX L"ERROR: " fmt L"\n", \
                     ##__VA_ARGS__);                            \
        OutputDebugStringW(_vl_buf);                            \
    } while (0)

#else

// Logging disabled — macros compile to nothing
#define VLOG(fmt, ...) ((void)0)
#define VERR(fmt, ...) ((void)0)

#endif // VOICELINK_NO_LOG

// ============================================================================
// VoiceLink SAPI Bridge — DLL Entry Point + COM Exports + Registry
// ============================================================================
//
// This file contains:
//   1. DllMain          — Called when the DLL is loaded/unloaded
//   2. DllGetClassObject — COM asks us for a class factory
//   3. DllCanUnloadNow   — COM asks if we can be removed from memory
//   4. DllRegisterServer — regsvr32 calls this to register us
//   5. DllUnregisterServer — regsvr32 /u calls this to unregister us
//
// Plus the registry code that makes our voices appear in Windows.
//
// THE 4 EXPORTS:
//   Every COM in-process server (DLL) must export exactly these 4 functions.
//   They're defined in voicelink.def so the linker exports them with the
//   correct names (no C++ name mangling).
//
// REGISTRATION:
//   When you run "regsvr32 voicelink_sapi.dll", Windows:
//   1. Loads our DLL (DllMain fires)
//   2. Calls DllRegisterServer
//   3. We write registry keys that tell Windows about our COM class and voices
//   4. Unloads the DLL
//
//   After this, our voices appear in any app's voice list.
// ============================================================================

// INITGUID must be defined BEFORE including guids.h in exactly ONE .cpp file.
// This makes DEFINE_GUID create actual GUID storage instead of extern declarations.
#include <initguid.h>

#include "guids.h"
#include "class_factory.h"
#include "debug.h"

#include <windows.h>
#include <sapi.h>
#include <string>
#include <vector>

// ============================================================================
// Global State
// ============================================================================

// Handle to our DLL module (needed to find our DLL path for registry)
HMODULE g_hModule = nullptr;

// Reference counting for DLL unloading.
// COM won't call FreeLibrary on us while either of these is > 0.
LONG g_lockCount = 0;   // Incremented by IClassFactory::LockServer(TRUE)
LONG g_objectCount = 0; // Incremented when a VoiceLinkEngine is created

// ============================================================================
// Voice Definitions
// ============================================================================
//
// Each entry here becomes a SAPI voice token in the registry.
// All voices share the same CLSID (same engine), but the engine reads
// the VoiceLinkVoiceId attribute to know which voice to request.
//
// The Language field uses LCID (Locale ID) in hex:
//   409 = en-US (English, United States)
//   809 = en-GB (English, United Kingdom)
//
// SAPI uses these attributes for voice selection:
//   - Name: display name in voice picker
//   - Gender: Male or Female
//   - Language: filters by locale
//   - Vendor: groups voices by provider

struct VoiceDefinition
{
    const wchar_t *tokenName;   // Registry key name (e.g., "VoiceLink_af_heart")
    const wchar_t *displayName; // Friendly name (e.g., "VoiceLink Kokoro Heart")
    const wchar_t *voiceId;     // ID sent to inference server (e.g., "af_heart")
