// ============================================================================
// DllMain — DLL Entry Point
// ============================================================================

BOOL APIENTRY DllMain(HMODULE hModule, DWORD reason, LPVOID /*lpReserved*/)
{
    switch (reason)
    {
    case DLL_PROCESS_ATTACH:
        // Save our module handle — we need it later to find our DLL path
        g_hModule = hModule;

        // Tell Windows we don't need DLL_THREAD_ATTACH/DETACH notifications.
        // This is a micro-optimization: Windows won't call DllMain for every
        // new thread, which saves a tiny bit of overhead in multi-threaded apps.
        DisableThreadLibraryCalls(hModule);

        VLOG(L"DLL loaded (DLL_PROCESS_ATTACH)");
        break;

    case DLL_PROCESS_DETACH:
        VLOG(L"DLL unloading (DLL_PROCESS_DETACH)");
        break;
    }
    return TRUE;
}

// ============================================================================
// DllGetClassObject — COM asks us for a class factory
// ============================================================================
//
// When an app calls CoCreateInstance(CLSID_VoiceLinkEngine, ...), COM:
//   1. Looks up CLSID in registry → finds our DLL path
//   2. Loads our DLL (DllMain fires)
//   3. Calls DllGetClassObject(CLSID_VoiceLinkEngine, IID_IClassFactory, ...)
//   4. We create a VoiceLinkClassFactory and return it
//   5. COM calls factory->CreateInstance() to get the actual engine
//
// The rclsid parameter is the CLSID of the class being requested.
// We only support CLSID_VoiceLinkEngine.

STDAPI DllGetClassObject(REFCLSID rclsid, REFIID riid, LPVOID *ppv)
{
    VLOG(L"DllGetClassObject called");

    if (!ppv)
        return E_POINTER;
    *ppv = nullptr;

    // Only our engine class is supported
    if (rclsid != CLSID_VoiceLinkEngine)
    {
        VERR(L"Unknown CLSID requested");
        return CLASS_E_CLASSNOTAVAILABLE;
    }

    // Create a class factory
    auto *factory = new (std::nothrow) VoiceLinkClassFactory();
    if (!factory)
    {
        return E_OUTOFMEMORY;
    }

    // Ask the factory for the requested interface (usually IID_IClassFactory)
    HRESULT hr = factory->QueryInterface(riid, ppv);
    factory->Release(); // Balance the ref from new (constructor sets it to 1)

    return hr;
}

// ============================================================================
// DllCanUnloadNow — COM asks if we can be removed from memory
// ============================================================================
//
// COM periodically calls this to see if it can free our DLL.
// We return S_OK (yes, unload us) only when:
//   - No VoiceLinkEngine objects exist (g_objectCount == 0)
//   - No server locks are held (g_lockCount == 0)
//
// If we return S_FALSE, COM keeps us loaded.

STDAPI DllCanUnloadNow()
{
    BOOL canUnload = (g_lockCount == 0 && g_objectCount == 0);
    VLOG(L"DllCanUnloadNow: locks=%ld, objects=%ld → %s",
         g_lockCount, g_objectCount, canUnload ? L"YES" : L"NO");
    return canUnload ? S_OK : S_FALSE;
}

// ============================================================================
// Registry Helpers
// ============================================================================

// Get the full path to our DLL
static std::wstring GetDllPath()
{
    wchar_t path[MAX_PATH] = {};
    GetModuleFileNameW(g_hModule, path, MAX_PATH);
    return path;
}

// Convert a GUID to string form: {XXXXXXXX-XXXX-XXXX-XXXX-XXXXXXXXXXXX}
static std::wstring GuidToString(const GUID &guid)
{
    wchar_t buf[64] = {};
    StringFromGUID2(guid, buf, _countof(buf));
    return buf;
}

// Create a registry key and optionally set its default value.
// If preserveExisting is true and the key already exists, the default
// value is NOT overwritten (preserves user renames).
static HRESULT CreateKeyWithDefault(HKEY hParent, const wchar_t *subkey,
                                    const wchar_t *defaultValue, HKEY *phkResult = nullptr,
                                    bool preserveExisting = false)
{
    HKEY hKey = nullptr;
    DWORD disposition = 0;
    LONG result = RegCreateKeyExW(
        hParent, subkey, 0, nullptr,
        REG_OPTION_NON_VOLATILE, KEY_WRITE | KEY_READ, nullptr,
        &hKey, &disposition);

    if (result != ERROR_SUCCESS)
    {
        VERR(L"RegCreateKeyEx failed for %s: %ld", subkey, result);
        return HRESULT_FROM_WIN32(result);
    }

    if (defaultValue)
    {
        bool shouldWrite = true;

        // If preserving existing names, only write if key is newly created
        // OR if the current value is empty
        if (preserveExisting && disposition == REG_OPENED_EXISTING_KEY)
        {
            // Check if there's already a non-empty value
            DWORD dataSize = 0;
            LONG queryResult = RegQueryValueExW(hKey, nullptr, nullptr, nullptr, nullptr, &dataSize);
            if (queryResult == ERROR_SUCCESS && dataSize > sizeof(wchar_t))
            {
                shouldWrite = false; // Already has a name, preserve it
            }
        }

        if (shouldWrite)
        {
            result = RegSetValueExW(
                hKey, nullptr, 0, REG_SZ,
                reinterpret_cast<const BYTE *>(defaultValue),
                static_cast<DWORD>((wcslen(defaultValue) + 1) * sizeof(wchar_t)));
        }
    }

    if (phkResult)
    {
        *phkResult = hKey;
    }
    else
    {
        RegCloseKey(hKey);
    }

    return (result == ERROR_SUCCESS) ? S_OK : HRESULT_FROM_WIN32(result);
}

// Set a named string value on an open registry key
static HRESULT SetStringValue(HKEY hKey, const wchar_t *name, const wchar_t *value)
{
    LONG result = RegSetValueExW(
        hKey, name, 0, REG_SZ,
        reinterpret_cast<const BYTE *>(value),
        static_cast<DWORD>((wcslen(value) + 1) * sizeof(wchar_t)));
    return (result == ERROR_SUCCESS) ? S_OK : HRESULT_FROM_WIN32(result);
}

// Recursively delete a registry key and all its subkeys
static HRESULT DeleteKeyRecursive(HKEY hParent, const wchar_t *subkey)
{
    LONG result = RegDeleteTreeW(hParent, subkey);
    if (result == ERROR_FILE_NOT_FOUND)
        return S_OK; // Already gone, that's fine
    return (result == ERROR_SUCCESS) ? S_OK : HRESULT_FROM_WIN32(result);
}

// ============================================================================
// DllRegisterServer — Register the COM class and SAPI voice tokens
// ============================================================================
//
// When you run "regsvr32 voicelink_sapi.dll", this function creates:
//
// 1. COM Class Registration:
//    HKCR\CLSID\{D7A5E2B1-...}\
//      (Default) = "VoiceLink TTS Engine"
//      \InprocServer32\
//        (Default) = "C:\...\voicelink_sapi.dll"
//        ThreadingModel = "Both"
//
// 2. SAPI Voice Tokens (one per voice):
//    HKLM\SOFTWARE\Microsoft\Speech\Voices\Tokens\VoiceLink_af_heart\
//      (Default) = "VoiceLink Kokoro Heart"
//      CLSID = "{D7A5E2B1-...}"
//      VoiceLinkVoiceId = "af_heart"
//      \Attributes\
//        Name = "VoiceLink Kokoro Heart"
//        Gender = "Female"
//        Language = "409"
//        Age = "Adult"
//        Vendor = "VoiceLink"
//
// After registration, every SAPI app will discover our voices.

STDAPI DllRegisterServer()
{
    VLOG(L"DllRegisterServer called");

    std::wstring dllPath = GetDllPath();
    std::wstring clsidStr = GuidToString(CLSID_VoiceLinkEngine);

    VLOG(L"DLL path: %s", dllPath.c_str());
    VLOG(L"CLSID: %s", clsidStr.c_str());

    // -----------------------------------------------------------------------
    // Step 1: Register the COM class in HKEY_CLASSES_ROOT\CLSID
    //
    // This tells COM: "CLSID {D7A5E2B1-...} maps to voicelink_sapi.dll"
    //
    // ThreadingModel = "Both" means our DLL works correctly in both
    // single-threaded apartment (STA) and multi-threaded apartment (MTA).
    // SAPI typically uses STA, but some apps use MTA.
    // -----------------------------------------------------------------------
    {
        std::wstring clsidKeyPath = std::wstring(L"CLSID\\") + clsidStr;

        HKEY hClsid = nullptr;
        HRESULT hr = CreateKeyWithDefault(HKEY_CLASSES_ROOT, clsidKeyPath.c_str(),
                                          L"VoiceLink TTS Engine", &hClsid);
        if (FAILED(hr))
            return hr;

        // InprocServer32 tells COM this is an in-process (DLL) server
        std::wstring inprocPath = clsidKeyPath + L"\\InprocServer32";
        HKEY hInproc = nullptr;
        hr = CreateKeyWithDefault(HKEY_CLASSES_ROOT, inprocPath.c_str(),
                                  dllPath.c_str(), &hInproc);
        if (FAILED(hr))
        {
            RegCloseKey(hClsid);
            return hr;
        }

        SetStringValue(hInproc, L"ThreadingModel", L"Both");
        RegCloseKey(hInproc);
        RegCloseKey(hClsid);

        VLOG(L"COM class registered");
    }

    // -----------------------------------------------------------------------
    // Step 2: Register each voice as a SAPI voice token
    //
    // Windows has TWO speech registries:
    //
    //   1. Classic SAPI 5:
    //      HKLM\SOFTWARE\Microsoft\Speech\Voices\Tokens\
    //      Used by: PowerShell, Balabolka, older .NET apps, classic SAPI apps
    //
    //   2. OneCore (Modern Speech API):
    //      HKLM\SOFTWARE\Microsoft\Speech_OneCore\Voices\Tokens\
    //      Used by: Thorium Reader, Chromium/Electron apps, Edge Read Aloud,
    //               Windows Narrator, UWP apps, modern .NET
    //
    // We register in BOTH so every app can discover VoiceLink voices.
    // The NaturalVoiceSAPIAdapter project does the same thing.
    // -----------------------------------------------------------------------
    const wchar_t *tokenRoots[] = {
        L"SOFTWARE\\Microsoft\\Speech\\Voices\\Tokens",
        L"SOFTWARE\\Microsoft\\Speech_OneCore\\Voices\\Tokens",
    };

    for (const wchar_t *tokensRoot : tokenRoots)
    {
        VLOG(L"Registering voices under: %s", tokensRoot);

        for (size_t i = 0; i < g_voiceCount; ++i)
        {
            const VoiceDefinition &voice = g_voices[i];

            std::wstring tokenPath = std::wstring(tokensRoot) + L"\\" + voice.tokenName;

            // Create the voice token key
            // preserveExisting=true: don't overwrite user-renamed display names
            HKEY hToken = nullptr;
            HRESULT hr = CreateKeyWithDefault(HKEY_LOCAL_MACHINE, tokenPath.c_str(),
                                              voice.displayName, &hToken,
                                              true /* preserveExisting */);
            if (FAILED(hr))
            {
                VERR(L"Failed to create token for %s", voice.tokenName);
                continue; // Try the next voice
            }

            // Set token values
            SetStringValue(hToken, L"CLSID", clsidStr.c_str());
            SetStringValue(hToken, L"VoiceLinkVoiceId", voice.voiceId);
            SetStringValue(hToken, L"VoiceLinkServerPort", L"7860");

            // Create the Attributes subkey
            HKEY hAttrs = nullptr;
            std::wstring attrsPath = tokenPath + L"\\Attributes";
            hr = CreateKeyWithDefault(HKEY_LOCAL_MACHINE, attrsPath.c_str(),
                                      nullptr, &hAttrs);
            if (SUCCEEDED(hr) && hAttrs)
            {
                // Only set Name if not already present (preserve renames)
                DWORD nameSize = 0;
                LONG qr = RegQueryValueExW(hAttrs, L"Name", nullptr, nullptr, nullptr, &nameSize);
                if (qr != ERROR_SUCCESS || nameSize <= sizeof(wchar_t))
                {
                    SetStringValue(hAttrs, L"Name", voice.displayName);
                }
                SetStringValue(hAttrs, L"Gender", voice.gender);
                SetStringValue(hAttrs, L"Language", voice.language);
                SetStringValue(hAttrs, L"Age", voice.age);
                SetStringValue(hAttrs, L"Vendor", L"VoiceLink");
                RegCloseKey(hAttrs);
            }

            RegCloseKey(hToken);
            VLOG(L"Registered voice: %s (%s)", voice.displayName, voice.voiceId);
        }
    }

    VLOG(L"DllRegisterServer completed: %zu voices x 2 registries", g_voiceCount);
    return S_OK;
}

// ============================================================================
// DllUnregisterServer — Remove all registry entries
// ============================================================================
//
// Called by "regsvr32 /u voicelink_sapi.dll".
// Removes everything DllRegisterServer created.

STDAPI DllUnregisterServer()
{
    VLOG(L"DllUnregisterServer called");

    std::wstring clsidStr = GuidToString(CLSID_VoiceLinkEngine);

    // -----------------------------------------------------------------------
    // Step 1: Remove the COM class registration
    // -----------------------------------------------------------------------
    {
        std::wstring clsidKeyPath = std::wstring(L"CLSID\\") + clsidStr;
        DeleteKeyRecursive(HKEY_CLASSES_ROOT, clsidKeyPath.c_str());
        VLOG(L"COM class unregistered");
    }

    // -----------------------------------------------------------------------
    // Step 2: Remove all voice tokens from BOTH registries
    // -----------------------------------------------------------------------
    const wchar_t *tokenRoots[] = {
        L"SOFTWARE\\Microsoft\\Speech\\Voices\\Tokens",
        L"SOFTWARE\\Microsoft\\Speech_OneCore\\Voices\\Tokens",
    };

    for (const wchar_t *tokensRoot : tokenRoots)
    {
        for (size_t i = 0; i < g_voiceCount; ++i)
        {
            std::wstring tokenPath = std::wstring(tokensRoot) + L"\\" + g_voices[i].tokenName;
            DeleteKeyRecursive(HKEY_LOCAL_MACHINE, tokenPath.c_str());
            VLOG(L"Unregistered voice: %s from %s", g_voices[i].tokenName, tokensRoot);
        }
    }

    VLOG(L"DllUnregisterServer completed");
    return S_OK;
}

// ============================================================================
// VoiceLink SAPI Bridge — GUID Definitions
// ============================================================================
//
// A GUID (Globally Unique Identifier) is a 128-bit number that uniquely
// identifies our COM class across ALL software on ALL computers in the world.
//
// When an app asks Windows "give me a VoiceLink engine", it uses our CLSID.
// Windows looks up this CLSID in the registry to find our DLL, loads it,
// and calls DllGetClassObject with this CLSID.
//
// HOW DEFINE_GUID WORKS:
//   - When INITGUID is defined (only in dllmain.cpp), DEFINE_GUID creates
//     the actual GUID constant in memory (allocates storage).
//   - In all other files, DEFINE_GUID creates an "extern" declaration
//     (just a reference, no storage).
//   - This ensures the GUID exists exactly once in the final DLL.
//
// GENERATING A GUID:
//   You can generate one with: PowerShell> [guid]::NewGuid()
//   Or in Visual Studio: Tools > Create GUID
//   The odds of collision are astronomically low (2^122 possibilities).
// ============================================================================

#pragma once

#include <windows.h>
#include <guiddef.h>

// {D7A5E2B1-3F8C-4E69-A1B4-7C2D9E0F5A38}
// CLSID for VoiceLinkEngine — the COM class that implements ISpTTSEngine.
//
// This is what goes in the registry:
//   HKCR\CLSID\{D7A5E2B1-3F8C-4E69-A1B4-7C2D9E0F5A38}\InprocServer32
//     (Default) = "C:\...\voicelink_sapi.dll"
//     ThreadingModel = "Both"
//
// And what each SAPI voice token references:
//   HKLM\SOFTWARE\Microsoft\Speech\Voices\Tokens\VoiceLink_af_heart
//     CLSID = "{D7A5E2B1-3F8C-4E69-A1B4-7C2D9E0F5A38}"
//
// Every voice token points to the SAME CLSID because it's the same engine.
// The engine reads the token's attributes to know which specific voice to use.
//
// clang-format off
DEFINE_GUID(CLSID_VoiceLinkEngine,
    0xd7a5e2b1, 0x3f8c, 0x4e69,
    0xa1, 0xb4, 0x7c, 0x2d, 0x9e, 0x0f, 0x5a, 0x38);
// clang-format on

// ============================================================================
// VoiceLink SAPI Bridge — HTTP Client (Implementation)
// ============================================================================
//
// This file contains:
//   1. TtsHttpClient — WinHTTP wrapper for streaming TTS
//   2. JSON construction helpers (no library needed)
//   3. UTF-16 → UTF-8 conversion
//
// WINHTTP HANDLE HIERARCHY:
//   Session (WinHttpOpen)
//     └── Connection (WinHttpConnect)
//           └── Request (WinHttpOpenRequest)  ← created per Speak() call
//
// The session and connection are long-lived (created once in Init).
// Each Speak() call creates a new request, uses it, then closes it.
// ============================================================================

#include "http_client.h"
#include "debug.h"

#include <winhttp.h>
#include <sstream>
#include <iomanip>
#include <vector>

#pragma comment(lib, "winhttp.lib")

// ============================================================================
// Retry / Timeout Configuration
// ============================================================================
//
// When the server is not running (e.g. after a reboot before VoiceLink GUI
// starts), the COM DLL should not hang or crash the calling app. Instead:
//   1. Set connection/receive timeouts so we don't block forever
//   2. Retry a few times with short delays (server may be starting up)
//   3. If all retries fail, return S_OK (silence) instead of E_FAIL
//
// This makes VoiceLink gracefully degrade: the app just hears nothing
// instead of getting an error dialog or crashing.
// ============================================================================
static constexpr int MAX_RETRIES = 3;               // Total attempts
static constexpr DWORD RETRY_DELAY_MS = 500;        // Wait between retries
static constexpr DWORD CONNECT_TIMEOUT_MS = 2000;   // TCP connect timeout
static constexpr DWORD SEND_TIMEOUT_MS = 5000;      // Time to send request
static constexpr DWORD RECEIVE_TIMEOUT_MS = 120000; // Time waiting for response headers (Qwen3 can take 60s+)

// ============================================================================
// TtsHttpClient Implementation
// ============================================================================

TtsHttpClient::~TtsHttpClient()
{
    Close();
}

HRESULT TtsHttpClient::Init(const wchar_t *host, INTERNET_PORT port)
{
    // Clean up any previous session
    Close();

    m_host = host;
    m_port = port;

    // -----------------------------------------------------------------------
    // Step 1: Create a WinHTTP session
    //
    // This is like opening a browser. It sets up the HTTP stack and
    // can be reused for many connections. The user agent string identifies
    // us in server logs (helpful for debugging).
    //
    // WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY: Use system proxy settings.
    // For localhost this doesn't matter, but it's good practice.
    // -----------------------------------------------------------------------
    m_hSession = WinHttpOpen(
        L"VoiceLink/1.0",                    // User agent
        WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY, // Proxy setting
        WINHTTP_NO_PROXY_NAME,               // Proxy name (auto)
        WINHTTP_NO_PROXY_BYPASS,             // Proxy bypass (auto)
        0                                    // Flags (synchronous mode)
    );

    if (!m_hSession)
    {
        VERR(L"WinHttpOpen failed: %lu", GetLastError());
        return E_FAIL;
    }

    // Set timeouts so we don't block forever if the server is down.
    // WinHttpSetTimeouts parameters: resolve, connect, send, receive (all in ms).
    WinHttpSetTimeouts(m_hSession,
                       CONNECT_TIMEOUT_MS,  // DNS resolve (N/A for 127.0.0.1 but harmless)
                       CONNECT_TIMEOUT_MS,  // TCP connect
                       SEND_TIMEOUT_MS,     // Send
                       RECEIVE_TIMEOUT_MS); // Receive

    // -----------------------------------------------------------------------
    // Step 2: Connect to the server
    //
    // This doesn't actually open a TCP connection yet — it just associates
    // a host:port with the session. The actual TCP connection happens when
    // we send a request (WinHttpSendRequest).
    //
    // For VoiceLink, this is always localhost:7860.
    // -----------------------------------------------------------------------
    m_hConnect = WinHttpConnect(
        m_hSession, // Session handle
        host,       // Server name (L"127.0.0.1")
        port,       // Port (7860)
        0           // Reserved
    );

    if (!m_hConnect)
    {
        VERR(L"WinHttpConnect failed: %lu", GetLastError());
        Close();
        return E_FAIL;
    }

    VLOG(L"HTTP client initialized: %s:%d", host, port);
    return S_OK;
}

void TtsHttpClient::Close()
{
    if (m_hConnect)
    {
        WinHttpCloseHandle(m_hConnect);
        m_hConnect = nullptr;
    }
    if (m_hSession)
    {
        WinHttpCloseHandle(m_hSession);
        m_hSession = nullptr;
    }
}

HRESULT TtsHttpClient::StreamSynthesize(
    const char *jsonBody,
    DWORD jsonBodyLen,
    const std::function<HRESULT(const BYTE *data, DWORD size)> &onChunk,
    const std::function<bool()> &checkAbort,
    ULONGLONG *pTotalAudioBytes,
    const wchar_t *endpoint)
{
    if (!m_hConnect)
    {
        VERR(L"StreamSynthesize called but client not initialized");
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Retry loop: if the server is down or starting up, retry a few times
    // before giving up. This handles the common case where the COM DLL is
    // loaded (e.g. by Thorium) before the VoiceLink GUI has started the
    // server. Each retry waits briefly to give the server time to come up.
    // -----------------------------------------------------------------------
    HRESULT lastHr = E_FAIL;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt)
    {
        if (attempt > 0)
        {
            VLOG(L"Retry attempt %d/%d after %lu ms delay",
                 attempt + 1, MAX_RETRIES, RETRY_DELAY_MS);
            Sleep(RETRY_DELAY_MS);

            // Check abort between retries (don't make the user wait)
            if (checkAbort && checkAbort())
            {
                VLOG(L"Synthesis aborted during retry wait");
                return S_OK; // SAPI convention: return S_OK on abort
            }
        }

        lastHr = StreamSynthesizeOnce(jsonBody, jsonBodyLen, onChunk,
                                      checkAbort, pTotalAudioBytes, endpoint);

        // Success or user abort: stop retrying
        if (SUCCEEDED(lastHr) || lastHr == E_ABORT)
            return (lastHr == E_ABORT) ? S_OK : lastHr;

        VERR(L"StreamSynthesize attempt %d failed: 0x%08lX", attempt + 1, lastHr);
    }

    // All retries exhausted. Return S_OK (silence) instead of E_FAIL.
    // This prevents the calling app from showing an error or crashing.
    // The user just hears nothing, which is much better than a crash.
    VERR(L"All %d attempts failed. Returning silence to avoid app crash.", MAX_RETRIES);
    return S_OK;
}

// ============================================================================
// StreamSynthesizeOnce — Single attempt at HTTP TTS synthesis
// ============================================================================

HRESULT TtsHttpClient::StreamSynthesizeOnce(
    const char *jsonBody,
    DWORD jsonBodyLen,
    const std::function<HRESULT(const BYTE *data, DWORD size)> &onChunk,
    const std::function<bool()> &checkAbort,
    ULONGLONG *pTotalAudioBytes,
    const wchar_t *endpoint)
{

    // -----------------------------------------------------------------------
    // Step 1: Create a POST request to /v1/tts
    //
    // This creates a request object. The actual HTTP request isn't sent yet.
    // Think of it like filling out a form before clicking "Submit".
    //
    // We use HTTP (not HTTPS) because it's localhost only. No data leaves
    // the machine, so encryption would be wasted CPU cycles.
    // -----------------------------------------------------------------------
    HINTERNET hRequest = WinHttpOpenRequest(
        m_hConnect,                   // Connection handle
        L"POST",                      // HTTP method
        endpoint,                     // URL path (e.g. /v1/tts or /v1/qwen3/tts)
        nullptr,                      // HTTP version (nullptr = HTTP/1.1)
        WINHTTP_NO_REFERER,           // Referrer (none)
        WINHTTP_DEFAULT_ACCEPT_TYPES, // Accept types (*/*)
        0                             // Flags (no HTTPS)
    );

    if (!hRequest)
    {
        VERR(L"WinHttpOpenRequest failed: %lu", GetLastError());
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 2: Set headers
    //
    // Content-Type tells the server we're sending JSON.
    // The server uses this to parse the request body correctly.
    // -----------------------------------------------------------------------
    const wchar_t *headers = L"Content-Type: application/json\r\n";
    BOOL headerOk = WinHttpAddRequestHeaders(
        hRequest,
        headers,
        static_cast<DWORD>(wcslen(headers)),
        WINHTTP_ADDREQ_FLAG_ADD);

    if (!headerOk)
    {
        VERR(L"WinHttpAddRequestHeaders failed: %lu", GetLastError());
        WinHttpCloseHandle(hRequest);
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 3: Send the request
    //
    // This actually opens the TCP connection (if not already open from a
    // previous request), sends the HTTP headers, and sends the JSON body.
    //
    // WinHttpSendRequest combines "send headers" and "write body" in one
    // call for simple requests. For larger bodies, you'd use
    // WinHttpWriteData separately.
    //
    // NOTE: This blocks until the server acknowledges the request.
    // For localhost, this is nearly instant (~0.1ms).
    // -----------------------------------------------------------------------
    BOOL sendOk = WinHttpSendRequest(
        hRequest,
        WINHTTP_NO_ADDITIONAL_HEADERS, 0,          // Additional headers (none)
        const_cast<char *>(jsonBody), jsonBodyLen, // Request body
        jsonBodyLen,                               // Total body length
        0                                          // Context (unused)
    );

    if (!sendOk)
    {
        DWORD err = GetLastError();
        VERR(L"WinHttpSendRequest failed: %lu (is the server running?)", err);
        WinHttpCloseHandle(hRequest);
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 4: Receive the response headers
    //
    // This blocks until the server sends back the HTTP response headers.
    // The server starts streaming audio immediately after, so this wait
    // includes the time for the model to generate the first audio chunk.
    //
    // For Kokoro on GPU: ~50-100ms
    // For Kokoro on CPU: ~200-500ms
    // -----------------------------------------------------------------------
    BOOL recvOk = WinHttpReceiveResponse(hRequest, nullptr);

    if (!recvOk)
    {
        VERR(L"WinHttpReceiveResponse failed: %lu", GetLastError());
        WinHttpCloseHandle(hRequest);
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 5: Check HTTP status code
    //
    // 200 = OK, everything else is an error.
    // Common errors:
    //   404 = wrong URL path
    //   422 = invalid JSON (Pydantic validation failed)
    //   500 = server crashed during synthesis
    // -----------------------------------------------------------------------
    DWORD statusCode = 0;
    DWORD statusSize = sizeof(statusCode);
    WinHttpQueryHeaders(
        hRequest,
        WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
        WINHTTP_HEADER_NAME_BY_INDEX,
        &statusCode,
        &statusSize,
        WINHTTP_NO_HEADER_INDEX);

    // -----------------------------------------------------------------------
    // Step 5b: Read X-Audio-Length header (if present)
    //
    // The server pre-generates all audio and reports the exact total byte
    // count in this header. The TTS engine uses it for perfectly
    // proportional SPEI_WORD_BOUNDARY event offsets, so Edge Read Aloud
    // text highlighting stays in sync with the audio.
    // -----------------------------------------------------------------------
    if (pTotalAudioBytes)
    {
        *pTotalAudioBytes = 0;
        wchar_t headerBuf[64] = {};
        DWORD headerBufSize = sizeof(headerBuf);
        BOOL hdrOk = WinHttpQueryHeaders(
            hRequest,
            WINHTTP_QUERY_CUSTOM,
            L"X-Audio-Length",
            headerBuf,
            &headerBufSize,
            WINHTTP_NO_HEADER_INDEX);
        if (hdrOk && headerBufSize > 0)
        {
            *pTotalAudioBytes = static_cast<ULONGLONG>(_wtoi64(headerBuf));
            VLOG(L"Server reported X-Audio-Length: %llu bytes", *pTotalAudioBytes);
        }
    }

    if (statusCode != 200)
    {
        VERR(L"Server returned HTTP %lu", statusCode);

        // Try to read the error body for debugging
        char errBuf[512] = {};
        DWORD errRead = 0;
        WinHttpReadData(hRequest, errBuf, sizeof(errBuf) - 1, &errRead);
        if (errRead > 0)
        {
            errBuf[errRead] = '\0';
            VLOG(L"Server error body: %hs", errBuf);
        }

        WinHttpCloseHandle(hRequest);
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 6: Read the streaming audio response
    //
    // The server sends raw PCM audio using HTTP chunked transfer encoding.
    // We read it in chunks and pass each one to SAPI immediately.
    //
    // Buffer size: 8192 bytes = ~170ms of audio at 24kHz/16-bit/mono
    // (24000 samples/sec * 2 bytes/sample = 48000 bytes/sec)
    // (8192 / 48000 = 0.170 seconds)
    //
    // Between chunks, we check if the app wants us to stop (abort).
    // This happens when the user clicks "stop" or navigates away.
    // -----------------------------------------------------------------------
    constexpr DWORD CHUNK_BUF_SIZE = 8192;
    BYTE buffer[CHUNK_BUF_SIZE];
    HRESULT result = S_OK;

    for (;;)
    {
        // Check if the caller wants us to abort
        if (checkAbort && checkAbort())
        {
            VLOG(L"Synthesis aborted by caller");
            result = E_ABORT;
            break;
        }

        // Read the next chunk of audio data
        // WinHttpReadData blocks until:
        //   - Data is available (returns that data)
        //   - Connection closes (returns 0 bytes = we're done)
        //   - Error occurs (returns FALSE)
        DWORD bytesRead = 0;
        BOOL readOk = WinHttpReadData(
            hRequest,
            buffer,
            CHUNK_BUF_SIZE,
            &bytesRead);

        if (!readOk)
        {
            VERR(L"WinHttpReadData failed: %lu", GetLastError());
            result = E_FAIL;
            break;
        }

        // 0 bytes = server finished sending audio
        if (bytesRead == 0)
        {
            break;
        }

        // Pass this chunk to SAPI (via the callback)
        HRESULT chunkResult = onChunk(buffer, bytesRead);
        if (FAILED(chunkResult))
        {
            VERR(L"onChunk callback failed: 0x%08lX", chunkResult);
            result = chunkResult;
            break;
        }
    }

    // -----------------------------------------------------------------------
    // Step 7: Clean up
    //
    // Close the request handle. The session and connection handles stay
    // open for the next Speak() call.
    // -----------------------------------------------------------------------
    WinHttpCloseHandle(hRequest);

    return result;
}

// ============================================================================
// JSON Helpers
// ============================================================================

std::string JsonEscapeUtf8(const std::string &input)
{
    // JSON string escaping rules (RFC 8259, Section 7):
    //   - Quotation mark (") → \"
    //   - Reverse solidus (\) → \\
    //   - Solidus (/) → \/ (optional, we skip this)
    //   - Backspace → \b
    //   - Form feed → \f
    //   - Newline → \n
    //   - Carriage return → \r
    //   - Tab → \t
    //   - Any character < U+0020 → \uXXXX

    std::string result;
    result.reserve(input.size() + input.size() / 8); // Pre-allocate ~12% extra

    for (unsigned char ch : input)
    {
        switch (ch)
        {
        case '"':
            result += "\\\"";
            break;
        case '\\':
            result += "\\\\";
            break;
        case '\b':
            result += "\\b";
            break;
        case '\f':
            result += "\\f";
            break;
        case '\n':
            result += "\\n";
            break;
        case '\r':
            result += "\\r";
            break;
        case '\t':
            result += "\\t";
            break;
        default:
            if (ch < 0x20)
            {
                // Control character → \u00XX
                char hex[8];
                snprintf(hex, sizeof(hex), "\\u%04x", ch);
                result += hex;
            }
            else
            {
                result += static_cast<char>(ch);
            }
            break;
        }
    }

    return result;
}

std::string BuildTtsRequestJson(const std::string &text,
                                const std::string &voiceId,
                                float speed)
{
    // Build JSON by hand. This is simple enough that a library would be
    // overkill, and we avoid adding any dependencies.
    //
    // Output format:
    //   {"text": "escaped text", "voice": "af_heart", "speed": 1.0, "format": "pcm_24k_16bit"}

    std::ostringstream json;
    json << "{\"text\": \"" << JsonEscapeUtf8(text)
         << "\", \"voice\": \"" << JsonEscapeUtf8(voiceId)
         << "\", \"speed\": " << std::fixed << std::setprecision(2) << speed
         << ", \"format\": \"pcm_24k_16bit\"}";

    return json.str();
}

// ============================================================================
// Encoding Helpers
// ============================================================================

std::string WideToUtf8(const wchar_t *wide, int len)
{
    // Windows uses UTF-16 (2 bytes per most characters, 4 bytes for rare ones).
    // Our HTTP server expects UTF-8 (1-4 bytes per character, ASCII-compatible).
    //
    // WideCharToMultiByte is the Windows API for this conversion.
    // We call it twice:
    //   1. First call with output buffer = nullptr → returns required size
    //   2. Second call with properly sized buffer → does the conversion
    //
    // This two-call pattern is common in Windows APIs that return
    // variable-length data.

    if (!wide || (len == 0))
    {
        return {};
    }

    // First call: get required buffer size
    int needed = WideCharToMultiByte(
        CP_UTF8, // Target encoding
        0,       // Flags (0 for UTF-8)
        wide,    // Source wide string
        len,     // Source length (-1 if null-terminated)
        nullptr, // Output buffer (nullptr = just tell me the size)
        0,       // Output buffer size
        nullptr, // Default character (must be nullptr for UTF-8)
        nullptr  // Used default character flag (must be nullptr for UTF-8)
    );

    if (needed <= 0)
    {
        return {};
    }

    // Second call: do the actual conversion
    std::string result(static_cast<size_t>(needed), '\0');
    WideCharToMultiByte(
        CP_UTF8, 0,
        wide, len,
        result.data(), needed,
        nullptr, nullptr);

    // If len was -1, the result includes a null terminator — trim it
    if (len == -1 && !result.empty() && result.back() == '\0')
    {
        result.pop_back();
    }

    return result;
}

// ============================================================================
// VoiceLink SAPI Bridge — HTTP Client (Header)
// ============================================================================
//
// This is how our COM DLL talks to the Python inference server.
//
// WHY HTTP? (and not pipes, shared memory, etc.)
//   1. HTTP is universal — the server can be tested with curl, Postman, etc.
//   2. HTTP chunked transfer encoding gives us natural streaming
//   3. HTTP keeps the two components loosely coupled
//   4. Localhost HTTP is fast — kernel bypasses the network stack
//
// WHY WINHTTP? (and not libcurl, Boost.Beast, etc.)
//   1. Zero dependencies — WinHTTP is built into Windows since XP
//   2. No DLL to ship, no version conflicts
//   3. Supports chunked transfer encoding natively
//   4. Async support if we need it later
//   5. TLS support if we ever need remote servers
//
// THE FLOW:
//   1. Open a session (once, reused across all requests)
//   2. Connect to localhost:7860 (once, reused)
//   3. For each Speak() call:
//      a. Open a POST request to /v1/tts
//      b. Send JSON body: {"text": "...", "voice": "af_heart"}
//      c. Read response in chunks (each chunk is raw PCM audio)
//      d. Pass each chunk to SAPI via callback
//      e. Close the request
// ============================================================================

#pragma once

#include <windows.h>
#include <winhttp.h>
#include <functional>
#include <string>

// Forward declaration — defined in winhttp.h but just in case
#ifndef HINTERNET
typedef LPVOID HINTERNET;
#endif

// ============================================================================
// TtsHttpClient — Streaming HTTP client for the TTS inference server
// ============================================================================
//
// Lifecycle:
//   1. Construct
//   2. Call Init() once (creates WinHTTP session + connection)
//   3. Call StreamSynthesize() for each Speak() call (can call many times)
//   4. Call Close() or let destructor handle it
//
// Thread Safety:
//   WinHTTP handles are thread-safe for different requests. Our COM engine
//   uses threading model "Both", so Speak() can be called from any thread.
//   Each Speak() call creates its own request handle, so concurrent calls
//   are safe as long as they don't share request handles.
// ============================================================================

class TtsHttpClient
{
public:
    TtsHttpClient() = default;
    ~TtsHttpClient();

    // Non-copyable (WinHTTP handles are not reference-counted)
    TtsHttpClient(const TtsHttpClient &) = delete;
    TtsHttpClient &operator=(const TtsHttpClient &) = delete;

    // -----------------------------------------------------------------------
    // Init — Create the WinHTTP session and connect to the server
    //
    // Call this once after construction. It creates:
    //   - A session handle (like opening a browser)
    //   - A connection handle (like typing in a URL)
    //
    // Returns S_OK on success, E_FAIL on error.
    // -----------------------------------------------------------------------
    HRESULT Init(const wchar_t *host, INTERNET_PORT port);

    // -----------------------------------------------------------------------
    // Close — Release all WinHTTP handles
    // -----------------------------------------------------------------------
    void Close();

    // -----------------------------------------------------------------------
    // StreamSynthesize — Send text to the server, get back streaming audio
    //
    // Parameters:
    //   jsonBody    — The JSON request body (UTF-8 encoded)
    //   jsonBodyLen — Length of jsonBody in bytes
    //   onChunk     — Called for each chunk of PCM audio data received.
    //                 Return S_OK to continue, any error to abort.
    //   checkAbort  — Called between chunks. Return true to abort.
    //
    // Returns:
    //   S_OK      — All audio received and delivered successfully
    //   E_ABORT   — Aborted by checkAbort() returning true
    //   E_FAIL    — HTTP error (server down, bad response, etc.)
    //
    // HOW STREAMING WORKS:
    //   The server uses HTTP chunked transfer encoding. This means it starts
    //   sending audio before the full synthesis is complete. We read each
    //   chunk as it arrives (WinHttpReadData blocks until data is available)
    //   and immediately pass it to SAPI. Result: audio starts playing within
    //   ~100ms of sending the request.
    // -----------------------------------------------------------------------
    HRESULT StreamSynthesize(
        const char *jsonBody,
        DWORD jsonBodyLen,
        const std::function<HRESULT(const BYTE *data, DWORD size)> &onChunk,
        const std::function<bool()> &checkAbort,
        ULONGLONG *pTotalAudioBytes = nullptr,
        const wchar_t *endpoint = L"/v1/tts");

    // -----------------------------------------------------------------------
    // IsInitialized — Check if Init() has been called successfully
    // -----------------------------------------------------------------------
    bool IsInitialized() const { return m_hConnect != nullptr; }

private:
    // Single attempt at HTTP synthesis (called by StreamSynthesize retry loop)
    HRESULT StreamSynthesizeOnce(
        const char *jsonBody,
        DWORD jsonBodyLen,
        const std::function<HRESULT(const BYTE *data, DWORD size)> &onChunk,
        const std::function<bool()> &checkAbort,
        ULONGLONG *pTotalAudioBytes,
        const wchar_t *endpoint);

    HINTERNET m_hSession = nullptr; // WinHTTP session (like a browser instance)
    HINTERNET m_hConnect = nullptr; // Connection to localhost:7860
    std::wstring m_host;
    INTERNET_PORT m_port = 0;
};

// ============================================================================
// JSON Helpers
// ============================================================================
//
// We construct JSON by hand instead of pulling in a JSON library.
// Our request is simple enough that this is cleaner than adding a dependency:
//   {"text": "Hello world", "voice": "af_heart", "speed": 1.0}
//
// The tricky part is escaping the text properly. JSON requires:
//   " → \"    (quote)
//   \ → \\    (backslash)
//   \n → \\n  (newline)
//   \r → \\r  (carriage return)
//   \t → \\t  (tab)
//   Control chars (0x00-0x1F) → \uXXXX
// ============================================================================

// Escape a UTF-8 string for safe inclusion in a JSON string value.
// The result does NOT include the surrounding quotes.
std::string JsonEscapeUtf8(const std::string &input);

// Build the complete JSON body for a TTS request.
std::string BuildTtsRequestJson(const std::string &text,
                                const std::string &voiceId,
                                float speed);

// ============================================================================
// Encoding Helpers
// ============================================================================

// Convert a wide string (UTF-16, what Windows/SAPI uses) to UTF-8
// (what our HTTP server expects).
std::string WideToUtf8(const wchar_t *wide, int len = -1);

// ============================================================================
// VoiceLink SAPI Bridge — TTS Engine (Implementation)
// ============================================================================
//
// This is where everything comes together. When an app says "speak this text",
// the journey is:
//
//   App → SAPI → VoiceLinkEngine::Speak()
//     → HTTP POST to localhost:7860/v1/tts
//     → Python server runs Kokoro model on GPU
//     → PCM audio streams back over HTTP
//     → We write each chunk to ISpTTSEngineSite::Write()
//     → SAPI plays the audio through the speakers
//
// THREADING NOTES:
//   Our COM class uses ThreadingModel="Both", meaning SAPI can call us
//   from any thread (STA or MTA). Speak() is the only method that does
//   significant work, and it's inherently per-call (no shared mutable
//   state across concurrent Speak calls). The HTTP client creates a new
//   request handle per Speak(), so concurrent calls are safe.
//
//   The one shared mutable thing is m_refCount, which is protected by
//   InterlockedIncrement/Decrement (atomic operations).
// ============================================================================

#include "tts_engine.h"
#include "debug.h"
#include "guids.h"

#include <sapi.h>
#include <sapiddk.h>
// NOTE: We intentionally do NOT include <sphelper.h> here.
// It contains GetVersionExW which is deprecated and triggers C4996.
// We don't need any of its helpers — we use ISpObjectToken methods directly.
#include <objbase.h> // CoTaskMemAlloc
#include <string>
#include <sstream>
#include <cmath>     // powf
#include <algorithm> // std::min, std::max
#include <vector>    // for volume scaling buffer
#include <cstdint>   // int16_t
#include <cwctype>   // iswspace (word boundary parsing)

// ============================================================================
// Constructor / Destructor
// ============================================================================

VoiceLinkEngine::VoiceLinkEngine()
    : m_refCount(1) // Start with ref count of 1 (creator holds a reference)
      ,
      m_pToken(nullptr), m_voiceId("af_heart") // Default voice if token doesn't specify
      ,
      m_model("kokoro") // Default model backend
      ,
      m_serverPort(7860) // Default port
      ,
      m_initialized(false)
{
    // Track how many of our objects exist globally.
    // DllCanUnloadNow checks this — COM won't unload our DLL while objects exist.
    InterlockedIncrement(&g_objectCount);
    VLOG(L"VoiceLinkEngine created (objects: %ld)", g_objectCount);
}

VoiceLinkEngine::~VoiceLinkEngine()
{
    VLOG(L"VoiceLinkEngine destroying");

    // Release the voice token if we have one
    if (m_pToken)
    {
        m_pToken->Release();
        m_pToken = nullptr;
    }

    // Close HTTP connection
    m_httpClient.Close();

    InterlockedDecrement(&g_objectCount);
    VLOG(L"VoiceLinkEngine destroyed (objects: %ld)", g_objectCount);
}

// ============================================================================
// IUnknown Implementation
// ============================================================================

STDMETHODIMP VoiceLinkEngine::QueryInterface(REFIID riid, void **ppv)
{
    // QueryInterface is COM's version of dynamic_cast / instanceof.
    //
    // The caller asks: "Do you support interface X?"
    // We check the requested IID against all interfaces we implement.
    // If yes: set *ppv to the correct vtable pointer and AddRef().
    // If no:  set *ppv to nullptr and return E_NOINTERFACE.
    //
    // IMPORTANT: The pointer we return must point to the correct vtable.
    // For ISpTTSEngine, "this" already points to the right vtable (it's first).
    // For ISpObjectWithToken, the compiler adjusts the pointer automatically
    // via the static_cast. This is why we use static_cast, not reinterpret_cast.

    if (!ppv)
        return E_POINTER;

    *ppv = nullptr;

    if (riid == IID_IUnknown)
    {
        // Convention: return the "primary" interface for IUnknown
        *ppv = static_cast<ISpTTSEngine *>(this);
    }
    else if (riid == IID_ISpTTSEngine)
    {
        *ppv = static_cast<ISpTTSEngine *>(this);
    }
    else if (riid == IID_ISpObjectWithToken)
    {
        *ppv = static_cast<ISpObjectWithToken *>(this);
    }
    else
    {
        return E_NOINTERFACE;
    }

    AddRef();
    return S_OK;
}

STDMETHODIMP_(ULONG)
VoiceLinkEngine::AddRef()
{
    // InterlockedIncrement is an atomic operation.
    // It's equivalent to "++m_refCount" but thread-safe.
    // We need this because multiple threads might AddRef/Release simultaneously.
    return InterlockedIncrement(&m_refCount);
}

STDMETHODIMP_(ULONG)
VoiceLinkEngine::Release()
{
    // InterlockedDecrement atomically decrements and returns the new value.
    // If it hits 0, nobody holds a reference to us anymore → self-destruct.
    //
    // WHY "delete this"? In COM, objects manage their own lifetime.
    // The caller doesn't "new" or "delete" us — they use AddRef/Release.
    // When the last Release() brings the count to 0, we clean up.
    LONG count = InterlockedDecrement(&m_refCount);
    if (count == 0)
    {
        delete this;
    }
    return static_cast<ULONG>(count);
}

// ============================================================================
// ISpObjectWithToken Implementation
// ============================================================================

STDMETHODIMP VoiceLinkEngine::SetObjectToken(ISpObjectToken *pToken)
{
    // SAPI calls this right after creating us, passing in the voice token
    // that identifies which voice we should be.
    //
    // The token lives in the registry at something like:
    //   HKLM\SOFTWARE\Microsoft\Speech\Voices\Tokens\VoiceLink_af_heart
    //
    // It has attributes we can read:
    //   VoiceLinkVoiceId = "af_heart"
    //   VoiceLinkServerPort = "7860"
    //
    // We read these to know which voice to request from the server.

    VLOG(L"SetObjectToken called");

    if (!pToken)
        return E_INVALIDARG;

    // Release old token if we had one, then store and AddRef the new one
    if (m_pToken)
    {
        m_pToken->Release();
    }
    m_pToken = pToken;
    m_pToken->AddRef();

    // -----------------------------------------------------------------------
    // Read custom attributes from the voice token
    // -----------------------------------------------------------------------

    // Voice ID (e.g., "af_heart", "am_adam")
    std::wstring voiceIdW = ReadTokenAttribute(L"VoiceLinkVoiceId");
    if (!voiceIdW.empty())
    {
        m_voiceId = WideToUtf8(voiceIdW.c_str());
        VLOG(L"Voice ID from token: %s", voiceIdW.c_str());
    }
    else
    {
        VLOG(L"No VoiceLinkVoiceId in token, using default: af_heart");
    }

    // Server port (default: 7860)
    std::wstring portW = ReadTokenAttribute(L"VoiceLinkServerPort");
    if (!portW.empty())
    {
        m_serverPort = static_cast<INTERNET_PORT>(_wtoi(portW.c_str()));
        VLOG(L"Server port from token: %d", m_serverPort);
    }

    // Model backend: "kokoro" (default) or "qwen3"
    std::wstring modelW = ReadTokenAttribute(L"VoiceLinkModel");
    if (!modelW.empty())
    {
        m_model = WideToUtf8(modelW.c_str());
        VLOG(L"Model from token: %s", modelW.c_str());
    }
    else
    {
        // Infer model from voice ID prefix
        if (m_voiceId.substr(0, 5) == "qwen3")
        {
            m_model = "qwen3";
            VLOG(L"Inferred model=qwen3 from voice ID prefix");
        }
        else
        {
            VLOG(L"No VoiceLinkModel in token, using default: kokoro");
        }
    }

    // -----------------------------------------------------------------------
    // Initialize the HTTP client
    // -----------------------------------------------------------------------
    HRESULT hr = m_httpClient.Init(L"127.0.0.1", m_serverPort);
    if (FAILED(hr))
    {
        VERR(L"Failed to initialize HTTP client");
        return hr;
    }

    m_initialized = true;
    VLOG(L"VoiceLinkEngine initialized: voice=%hs, port=%d", m_voiceId.c_str(), m_serverPort);
    return S_OK;
}

STDMETHODIMP VoiceLinkEngine::GetObjectToken(ISpObjectToken **ppToken)
{
    // SAPI occasionally asks us which token we're associated with.
    // Simple: return the token that was given to us in SetObjectToken.

    if (!ppToken)
        return E_POINTER;

    *ppToken = m_pToken;
    if (m_pToken)
    {
        m_pToken->AddRef(); // Caller gets a reference, must Release() it
    }
    return S_OK;
}

// ============================================================================
// ISpTTSEngine::GetOutputFormat
// ============================================================================

STDMETHODIMP VoiceLinkEngine::GetOutputFormat(
    const GUID * /*pTargetFmtId*/,
    const WAVEFORMATEX * /*pTargetWaveFormatEx*/,
    GUID *pDesiredFmtId,
    WAVEFORMATEX **ppCoMemDesiredWaveFormatEx)
{
    // SAPI calls this before Speak() to ask what audio format we'll produce.
    //
    // We ALWAYS produce: 24kHz, 16-bit, mono PCM
    // This matches Kokoro's native output — no resampling, no quality loss.
    //
    // IMPORTANT: We must allocate the WAVEFORMATEX with CoTaskMemAlloc.
    // SAPI owns the memory after we return it and will CoTaskMemFree it.
    // Using "new" or "malloc" here would cause a crash later.
    //
    // WHY CoTaskMemAlloc?
    //   COM has a strict rule: if memory crosses a COM boundary (from us to
    //   SAPI), it must use the COM allocator (CoTaskMemAlloc/CoTaskMemFree).
    //   This ensures both sides agree on HOW to free the memory.
    //   Regular new/delete or malloc/free could use different heaps.

    VLOG(L"GetOutputFormat called");

    if (!pDesiredFmtId || !ppCoMemDesiredWaveFormatEx)
        return E_POINTER;

    // Allocate WAVEFORMATEX using COM's allocator
    auto *pwfx = static_cast<WAVEFORMATEX *>(
        CoTaskMemAlloc(sizeof(WAVEFORMATEX)));

    if (!pwfx)
        return E_OUTOFMEMORY;

    // Fill in 24kHz, 16-bit, mono PCM format
    //
    // WAVEFORMATEX fields:
    //   wFormatTag     = 1 (WAVE_FORMAT_PCM)
    //   nChannels      = 1 (mono)
    //   nSamplesPerSec = 24000 (24kHz)
    //   wBitsPerSample = 16
    //   nBlockAlign    = nChannels * wBitsPerSample / 8 = 2 bytes
    //   nAvgBytesPerSec = nSamplesPerSec * nBlockAlign = 48000 bytes/sec
    //   cbSize         = 0 (no extra data after this struct)
    pwfx->wFormatTag = WAVE_FORMAT_PCM;
    pwfx->nChannels = 1;
    pwfx->nSamplesPerSec = 24000;
    pwfx->wBitsPerSample = 16;
    pwfx->nBlockAlign = pwfx->nChannels * pwfx->wBitsPerSample / 8;   // 2
    pwfx->nAvgBytesPerSec = pwfx->nSamplesPerSec * pwfx->nBlockAlign; // 48000
    pwfx->cbSize = 0;

    // Tell SAPI we're producing WAV format (PCM)
    *pDesiredFmtId = SPDFID_WaveFormatEx;
    *ppCoMemDesiredWaveFormatEx = pwfx;

    return S_OK;
}

// ============================================================================
// ISpTTSEngine::Speak — THE MAIN EVENT
// ============================================================================

STDMETHODIMP VoiceLinkEngine::Speak(
    DWORD /*dwSpeakFlags*/,
    REFGUID /*rguidFormatId*/,
    const WAVEFORMATEX * /*pWaveFormatEx*/,
    const SPVTEXTFRAG *pTextFragList,
    ISpTTSEngineSite *pOutputSite)
{
    // -----------------------------------------------------------------------
    // This is where the magic happens. The entire purpose of VoiceLink
    // flows through this one method:
    //
    //   SAPI gives us text → we send it to Kokoro → we stream audio back
    //
    // The pOutputSite is our lifeline to SAPI. It lets us:
    //   - Write audio data: pOutputSite->Write(pcmData, byteCount, &written)
    //   - Check for abort: pOutputSite->GetActions() & SPVES_ABORT
    //   - Report events: pOutputSite->EventNotify(event) (future)
    // -----------------------------------------------------------------------

    VLOG(L"Speak() called");

    if (!pTextFragList || !pOutputSite)
        return E_INVALIDARG;

    if (!m_initialized || !m_httpClient.IsInitialized())
    {
        VERR(L"Speak() called but engine not initialized");
        return E_FAIL;
    }

    // -----------------------------------------------------------------------
    // Step 1: Extract text and fragment-level rate from SPVTEXTFRAG list
    //
    // SAPI doesn't give us a simple string. It gives us a linked list of
    // "text fragments", each with:
    //   - pTextStart: pointer to the text (NOT null-terminated!)
    //   - ulTextLen: number of characters
    //   - State.eAction: what to do (speak, silence, spell out, etc.)
    //   - State.RateAdj: per-fragment rate adjustment (additive with base rate)
    //   - pNext: next fragment
    //
    // Some apps (like Chromium/Thorium) pass speed through the fragment's
    // RateAdj field rather than (or in addition to) ISpVoice::SetRate().
    // We capture the max RateAdj to combine with the base rate.
    // -----------------------------------------------------------------------
    LONG maxFragRateAdj = 0;
    std::string textUtf8 = ExtractText(pTextFragList, &maxFragRateAdj);

    if (textUtf8.empty())
    {
        VLOG(L"No text to speak, returning S_OK");
        return S_OK;
    }

    VLOG(L"Text to synthesize: %zu bytes (UTF-8)", textUtf8.size());

    // -----------------------------------------------------------------------
    // Step 2: Get rate and volume from SAPI
    //
    // ISpTTSEngineSite provides rate and volume that the app or user set:
    //   GetRate()   → LONG from -10 to +10 (0 = normal, base rate)
    //   GetVolume() → USHORT from 0 to 100 (100 = full volume)
    //
    // RATE MAPPING (Thorium/Chromium compatible):
    //   Chromium maps its Web Speech API rate (0.5x-3x) to SAPI rate using
    //   approximately: sapi_rate = (int)((web_rate - 1) * 2)
    //   So Thorium 3x → SAPI rate 4, Thorium 2x → rate 2, etc.
    //
    //   To reverse this, we use a linear mapping:
    //     speed = 1.0 + effectiveRate * 0.5
    //
    //   This gives:
    //     Rate -1 → 0.50x (Thorium 0.5x)
    //     Rate  0 → 1.00x (normal)
    //     Rate  1 → 1.50x (Thorium 1.5x)
    //     Rate  2 → 2.00x (Thorium 2x)
    //     Rate  3 → 2.50x (Thorium 2.5x)
    //     Rate  4 → 3.00x (Thorium 3x)
    //     Rate  6 → 4.00x (clamped to server max)
    //   Clamped to [0.25, 4.0] to match server limits.
    //
    //   The effective rate combines the base rate (GetRate) with the
    //   per-fragment RateAdj from the SPVTEXTFRAG state. Some apps set
    //   one, some set the other, some set both.
    //
    // VOLUME MAPPING:
    //   We scale each PCM sample by (volume / 100.0).
    //   Volume 100 = no change, Volume 50 = half amplitude, Volume 0 = silence.
    // -----------------------------------------------------------------------

    LONG sapiRate = 0;
    pOutputSite->GetRate(&sapiRate);

    USHORT sapiVolume = 100;
    pOutputSite->GetVolume(&sapiVolume);

    // Combine base rate with fragment-level rate adjustment
    LONG effectiveRate = sapiRate + maxFragRateAdj;

    // Linear mapping: speed = 1 + rate * 0.5
    // Matches Chromium's inverse: when Thorium says 3x, rate=4, speed=3.0
    float speed = 1.0f + static_cast<float>(effectiveRate) * 0.5f;
    speed = (std::max)(0.25f, (std::min)(4.0f, speed)); // Clamp to server limits

    // Volume as a fraction for PCM scaling
    float volumeScale = static_cast<float>(sapiVolume) / 100.0f;

    VLOG(L"SAPI baseRate=%ld, fragRateAdj=%ld, effective=%ld → speed=%.2f, volume=%u → scale=%.2f",
         sapiRate, maxFragRateAdj, effectiveRate, speed, sapiVolume, volumeScale);

    // -----------------------------------------------------------------------
    // Step 2b: Parse word boundaries for SAPI text-tracking events
    //
    // SAPI clients (notably Edge Read Aloud) use SPEI_WORD_BOUNDARY events
    // to highlight the currently-spoken word. Without these events, Edge
    // shows no text highlighting even though the audio plays correctly.
    //
    // We also fire SPEI_SENTENCE_BOUNDARY events at sentence starts so
    // Edge can jump between sentences when the user clicks in the text.
    //
    // We walk the fragment list, split on whitespace, and record each word's
    // character position (via ulTextSrcOffset) and length. During streaming
    // we fire events proportionally based on each word's position as a
    // fraction of total text length.
    // -----------------------------------------------------------------------
    struct WordBoundary
    {
        ULONG charPos;  // Character offset in original input text
        ULONG charLen;  // Word length in characters
        bool sentStart; // Is this the first word of a sentence?
    };
    std::vector<WordBoundary> wordBoundaries;
    ULONG totalTextChars = 0; // Total character span of all fragments

    for (const SPVTEXTFRAG *frag = pTextFragList; frag; frag = frag->pNext)
    {
        if (frag->State.eAction != SPVA_Speak || !frag->pTextStart || frag->ulTextLen == 0)
            continue;

        ULONG baseOff = frag->ulTextSrcOffset;
        const wchar_t *t = frag->pTextStart;
        ULONG len = frag->ulTextLen;

        // Track total text span (last char position + 1)
        if (baseOff + len > totalTextChars)
            totalTextChars = baseOff + len;

        bool nextIsSentStart = true; // First word of a fragment starts a sentence
        ULONG i = 0;
        while (i < len)
        {
            while (i < len && std::iswspace(t[i]))
                i++;
            if (i >= len)
                break;

            ULONG ws = i;
            while (i < len && !std::iswspace(t[i]))
                i++;

            wordBoundaries.push_back({baseOff + ws, i - ws, nextIsSentStart});
            nextIsSentStart = false;

            // Check if this word ends with sentence-ending punctuation
            wchar_t lastChar = t[i - 1];
            if (lastChar == L'.' || lastChar == L'!' || lastChar == L'?' ||
                lastChar == L'\u2026') // ellipsis
            {
                nextIsSentStart = true; // Next word starts a new sentence
            }
        }
    }

    // Estimated total audio bytes: 48000 bytes/sec ÷ ~15 chars/sec = 3200 bytes/char.
    // This is a rough fallback estimate. The server reports the EXACT total
    // audio byte count via the X-Audio-Length header, which we use if available.
    // The estimate is only used as a fallback when the header is missing.
    float estTotalAudioBytes = static_cast<float>(totalTextChars) * 3200.0f / speed;
    size_t nextWordIdx = 0;

    VLOG(L"Parsed %zu word boundaries, totalChars=%lu, estAudio=%.0f bytes",
         wordBoundaries.size(), totalTextChars, estTotalAudioBytes);

    // -----------------------------------------------------------------------
    // Step 3: Build the JSON request for the inference server
    // -----------------------------------------------------------------------
    std::string jsonBody = BuildTtsRequestJson(textUtf8, m_voiceId, speed);

    // Choose endpoint based on model backend
    // Kokoro: /v1/tts (the original endpoint)
    // Qwen3:  /v1/qwen3/tts (the Qwen3-specific endpoint)
    const wchar_t *endpoint = (m_model == "qwen3") ? L"/v1/qwen3/tts" : L"/v1/tts";

    // -----------------------------------------------------------------------
    // Step 4: Send to server and stream audio back
    //
    // The onChunk callback writes each chunk of PCM audio to SAPI.
    // The checkAbort callback checks if the app wants us to stop.
    //
    // The server pre-generates all audio and reports the exact byte count
    // in the X-Audio-Length header. We use this for perfectly proportional
    // word boundary events (no drift between highlighting and audio).
    // -----------------------------------------------------------------------

    // Track total bytes written (for logging)
    ULONG totalBytesWritten = 0;

    // The server reports exact audio length via X-Audio-Length header.
    // If available, this replaces our rough estimate for perfect timing.
    ULONGLONG serverAudioBytes = 0;

    HRESULT hr = m_httpClient.StreamSynthesize(
        jsonBody.c_str(),
        static_cast<DWORD>(jsonBody.size()),

        // onChunk: called for each chunk of PCM audio from the server
        [&](const BYTE *data, DWORD size) -> HRESULT
        {
            // ---------------------------------------------------------------
            // Apply volume scaling if needed
            //
            // The audio is 16-bit signed PCM (int16). To adjust volume,
            // we multiply each sample by the volume fraction.
            //
            // We only do this work if volume != 100 (the common case
            // skips the copy entirely — zero overhead).
            // ---------------------------------------------------------------

            const BYTE *writeData = data;
            std::vector<BYTE> scaledBuf;

            if (volumeScale < 0.999f) // Only scale if volume < 100
            {
                scaledBuf.resize(size);
                const int16_t *src = reinterpret_cast<const int16_t *>(data);
                int16_t *dst = reinterpret_cast<int16_t *>(scaledBuf.data());
                DWORD sampleCount = size / sizeof(int16_t);

                for (DWORD i = 0; i < sampleCount; ++i)
                {
                    // Scale and clamp to int16 range
                    float scaled = static_cast<float>(src[i]) * volumeScale;
                    scaled = (std::max)(-32768.0f, (std::min)(32767.0f, scaled));
                    dst[i] = static_cast<int16_t>(scaled);
                }

                writeData = scaledBuf.data();
            }

            // Write audio data to SAPI's output site.
            //
            // ISpTTSEngineSite::Write() is like writing to a pipe:
            //   - SAPI buffers the data internally
            //   - The audio subsystem reads from the buffer and plays it
            //   - Write() blocks if the buffer is full (backpressure)
            //
            // The &written output tells us how many bytes SAPI accepted.
            // Usually it's all of them, but we should check.
            ULONG written = 0;
            HRESULT writeHr = pOutputSite->Write(writeData, size, &written);

            if (FAILED(writeHr))
            {
                VERR(L"ISpTTSEngineSite::Write failed: 0x%08lX", writeHr);
                return writeHr;
            }

            totalBytesWritten += written;

            // ---------------------------------------------------------------
            // Use server-reported exact audio length if available.
            //
            // The server pre-generates all audio and sends the total byte
            // count in the X-Audio-Length header. Using the EXACT total
            // instead of our rough estimate gives perfect proportional
            // word-boundary event timing — no highlight drift.
            // ---------------------------------------------------------------
            if (serverAudioBytes > 0 && estTotalAudioBytes != static_cast<float>(serverAudioBytes))
            {
                VLOG(L"Updating estTotalAudioBytes: %.0f → %llu (from server)",
                     estTotalAudioBytes, serverAudioBytes);
                estTotalAudioBytes = static_cast<float>(serverAudioBytes);
            }

            // ---------------------------------------------------------------
            // Fire SPEI_WORD_BOUNDARY (and SPEI_SENTENCE_BOUNDARY) events
            // for words whose proportional audio offset we have now passed.
            //
            // Each word's audio offset is:
            //   (charPos / totalTextChars) * estTotalAudioBytes
            //
            // With the server-reported total, this is exact. With the
            // fallback estimate, it's approximate.
            // ---------------------------------------------------------------
            while (nextWordIdx < wordBoundaries.size())
            {
                float fraction = (totalTextChars > 0)
                                     ? static_cast<float>(wordBoundaries[nextWordIdx].charPos) / totalTextChars
                                     : 0.0f;
                ULONGLONG estOffset = static_cast<ULONGLONG>(fraction * estTotalAudioBytes);

                if (estOffset <= totalBytesWritten)
                {
                    // Fire sentence boundary before the first word of a sentence
                    if (wordBoundaries[nextWordIdx].sentStart)
                    {
                        // Calculate sentence length (chars to next sentence or end)
                        ULONG sentLen = 0;
                        for (size_t si = nextWordIdx + 1; si < wordBoundaries.size(); si++)
                        {
                            if (wordBoundaries[si].sentStart)
                            {
                                sentLen = wordBoundaries[si].charPos - wordBoundaries[nextWordIdx].charPos;
                                break;
                            }
                        }
                        if (sentLen == 0 && totalTextChars > wordBoundaries[nextWordIdx].charPos)
                            sentLen = totalTextChars - wordBoundaries[nextWordIdx].charPos;

                        SPEVENT sentEvt = {};
                        sentEvt.eEventId = SPEI_SENTENCE_BOUNDARY;
                        sentEvt.elParamType = SPET_LPARAM_IS_UNDEFINED;
                        sentEvt.ullAudioStreamOffset = estOffset;
                        sentEvt.wParam = static_cast<WPARAM>(sentLen);
                        sentEvt.lParam = static_cast<LPARAM>(wordBoundaries[nextWordIdx].charPos);
                        pOutputSite->AddEvents(&sentEvt, 1);
                    }

                    SPEVENT evt = {};
                    evt.eEventId = SPEI_WORD_BOUNDARY;
                    evt.elParamType = SPET_LPARAM_IS_UNDEFINED;
                    evt.ullAudioStreamOffset = estOffset;
                    evt.wParam = static_cast<WPARAM>(wordBoundaries[nextWordIdx].charLen);
                    evt.lParam = static_cast<LPARAM>(wordBoundaries[nextWordIdx].charPos);
                    pOutputSite->AddEvents(&evt, 1);
                    nextWordIdx++;
                }
                else
                    break;
            }

            return S_OK;
        },

        // checkAbort: called between chunks to see if we should stop
        [&]() -> bool
        {
            // GetActions() returns a bitmask of pending actions.
            // IMPORTANT: GetActions() CLEARS the flags after reading,
            // so we must handle all flags in a single call.
            DWORD actions = pOutputSite->GetActions();

            if (actions & SPVES_ABORT)
            {
                VLOG(L"Abort requested by SAPI");
                return true;
            }

            // SPVES_SKIP: Edge Read Aloud sends this when the user clicks
            // on a different position in the text. We acknowledge the skip
            // and abort so Edge can start a new Speak() from that position.
            if (actions & SPVES_SKIP)
            {
                SPVSKIPTYPE skipType;
                long skipCount;
                if (SUCCEEDED(pOutputSite->GetSkipInfo(&skipType, &skipCount)))
                {
                    pOutputSite->CompleteSkip(skipCount);
                }
                VLOG(L"Skip requested by SAPI — aborting for repositioning");
                return true;
            }

            return false;
        },
        &serverAudioBytes,
        endpoint);

    // Flush any remaining word-boundary events whose estimated offset
    // exceeded the actual audio length (our estimate was too high).
    // Only flush on successful completion — not on abort/skip.
    if (SUCCEEDED(hr))
        while (nextWordIdx < wordBoundaries.size())
        {
            if (wordBoundaries[nextWordIdx].sentStart)
            {
                ULONG sentLen = 0;
                for (size_t si = nextWordIdx + 1; si < wordBoundaries.size(); si++)
                {
                    if (wordBoundaries[si].sentStart)
                    {
                        sentLen = wordBoundaries[si].charPos - wordBoundaries[nextWordIdx].charPos;
                        break;
                    }
                }
                if (sentLen == 0 && totalTextChars > wordBoundaries[nextWordIdx].charPos)
                    sentLen = totalTextChars - wordBoundaries[nextWordIdx].charPos;

                SPEVENT sentEvt = {};
                sentEvt.eEventId = SPEI_SENTENCE_BOUNDARY;
                sentEvt.elParamType = SPET_LPARAM_IS_UNDEFINED;
                sentEvt.ullAudioStreamOffset = totalBytesWritten;
                sentEvt.wParam = static_cast<WPARAM>(sentLen);
                sentEvt.lParam = static_cast<LPARAM>(wordBoundaries[nextWordIdx].charPos);
                pOutputSite->AddEvents(&sentEvt, 1);
            }

            SPEVENT evt = {};
            evt.eEventId = SPEI_WORD_BOUNDARY;
            evt.elParamType = SPET_LPARAM_IS_UNDEFINED;
            evt.ullAudioStreamOffset = totalBytesWritten;
            evt.wParam = static_cast<WPARAM>(wordBoundaries[nextWordIdx].charLen);
            evt.lParam = static_cast<LPARAM>(wordBoundaries[nextWordIdx].charPos);
            pOutputSite->AddEvents(&evt, 1);
            nextWordIdx++;
        }

    if (hr == E_ABORT)
    {
        VLOG(L"Speak() aborted after %lu bytes", totalBytesWritten);
    }
    else if (FAILED(hr))
    {
        VERR(L"Speak() failed: 0x%08lX (wrote %lu bytes before failure)",
             hr, totalBytesWritten);
    }
    else
    {
        VLOG(L"Speak() completed: %lu bytes of audio streamed", totalBytesWritten);
    }

    // Return S_OK even on abort — that's the SAPI convention.
    // Errors are only for real failures (server down, etc.)
    return (hr == E_ABORT) ? S_OK : hr;
}

// ============================================================================
// Private Helpers
// ============================================================================

std::string VoiceLinkEngine::ExtractText(const SPVTEXTFRAG *pTextFragList, LONG *pMaxRateAdj)
{
    // Walk the linked list and concatenate all speakable text.
    // Also capture the maximum RateAdj across all fragments, so we can
    // factor it into the speed calculation.
    //
    // SPVTEXTFRAG::State.eAction tells us what each fragment represents:
    //   SPVA_Speak   — Normal text to speak (most common)
    //   SPVA_Silence — Insert a pause (we could send a silence buffer)
    //   SPVA_SpellOut — Spell each character ("C-A-T")
    //   SPVA_Bookmark — An event marker (we ignore these)
    //   etc.
    //
    // For v1, we handle Speak and SpellOut. Everything else is skipped.

    std::wstring fullText;
    LONG maxRate = 0;

    for (const SPVTEXTFRAG *frag = pTextFragList; frag; frag = frag->pNext)
    {
        if (!frag->pTextStart || frag->ulTextLen == 0)
            continue;

        // Log fragment-level rate and volume for diagnostics
        VLOG(L"Fragment: action=%d, rateAdj=%ld, volume=%u, len=%lu",
             frag->State.eAction, frag->State.RateAdj,
             frag->State.Volume, frag->ulTextLen);

        // Track the highest RateAdj across fragments
        // (Use absolute max — if any fragment wants faster, honor it)
        if (frag->State.RateAdj > maxRate || frag == pTextFragList)
            maxRate = frag->State.RateAdj;

        switch (frag->State.eAction)
        {
        case SPVA_Speak:
            // Normal speech — just append the text
            fullText.append(frag->pTextStart, frag->ulTextLen);
            fullText += L' '; // Space between fragments
            break;

        case SPVA_SpellOut:
            // Spell each character with pauses
            // "cat" → "c. a. t."
            for (ULONG i = 0; i < frag->ulTextLen; ++i)
            {
                fullText += frag->pTextStart[i];
                fullText += L". ";
            }
            break;

        case SPVA_Silence:
            // TODO: Could insert a "..." or send silence audio
            break;

        default:
            // Skip bookmarks, pronunciations, etc.
            break;
        }
    }

    // Trim trailing whitespace
    while (!fullText.empty() && fullText.back() == L' ')
    {
        fullText.pop_back();
    }

    // Output the max fragment rate adjustment
    if (pMaxRateAdj)
        *pMaxRateAdj = maxRate;

    // Convert UTF-16 (Windows native) to UTF-8 (HTTP server expects)
    return WideToUtf8(fullText.c_str(), static_cast<int>(fullText.size()));
}

std::wstring VoiceLinkEngine::ReadTokenAttribute(const wchar_t *attrName)
{
    // Read a custom attribute from our voice token in the registry.
    //
    // The token has an "Attributes" subkey with values like:
    //   Name = "VoiceLink Kokoro Heart"
    //   VoiceLinkVoiceId = "af_heart"
    //
    // ISpObjectToken provides methods to read these without touching
    // the registry directly.

    if (!m_pToken || !attrName)
        return {};

    // SpGetSubTokenFromToken reads from the Attributes subkey
    // But for custom attributes at the token level, we use GetStringValue
    LPWSTR value = nullptr;
    HRESULT hr = m_pToken->GetStringValue(attrName, &value);

    if (SUCCEEDED(hr) && value)
    {
        std::wstring result(value);
        CoTaskMemFree(value); // SAPI allocates with CoTaskMemAlloc
        return result;
    }

    // Try the Attributes subkey
    ISpDataKey *pAttrs = nullptr;
    hr = m_pToken->OpenKey(L"Attributes", &pAttrs);
    if (SUCCEEDED(hr) && pAttrs)
    {
        hr = pAttrs->GetStringValue(attrName, &value);
        pAttrs->Release();

        if (SUCCEEDED(hr) && value)
        {
            std::wstring result(value);
            CoTaskMemFree(value);
            return result;
        }
    }

    return {};
}

// ============================================================================
// VoiceLink SAPI Bridge — TTS Engine (Header)
// ============================================================================
//
// This is the heart of VoiceLink. VoiceLinkEngine is the COM object that
// Windows sees as a "TTS voice". It implements two interfaces:
//
//   ISpTTSEngine — The engine that turns text into audio
//     - Speak(): receives text, returns audio
//     - GetOutputFormat(): tells SAPI what audio format we produce
//
//   ISpObjectWithToken — Links the engine to its registry token
//     - SetObjectToken(): SAPI tells us which voice token created us
//     - GetObjectToken(): SAPI asks which token we're associated with
//
// Plus IUnknown (the base of all COM objects):
//     - QueryInterface(): "Do you support this interface?"
//     - AddRef(): "I need you, don't go away"
//     - Release(): "I'm done with you" (destructs when count hits 0)
//
// LIFECYCLE:
//   1. App calls CoCreateInstance(CLSID_VoiceLinkEngine, ISpTTSEngine)
//   2. COM calls our DllGetClassObject → ClassFactory::CreateInstance
//   3. SAPI calls SetObjectToken(token for "VoiceLink Kokoro Heart")
//   4. SAPI calls GetOutputFormat() → we say "24kHz, 16-bit, mono"
//   5. For each utterance, SAPI calls Speak(text, site)
//   6. We extract text, HTTP POST to server, stream audio back via site
//   7. App calls Release() → ref count hits 0 → destructor runs
//
// VTABLE MEMORY LAYOUT:
//   Because we inherit from TWO interfaces (ISpTTSEngine + ISpObjectWithToken),
//   and both inherit from IUnknown, our C++ object has TWO vtable pointers:
//
//   VoiceLinkEngine object in memory:
//   ┌─────────────────────────────────┐
//   │ vtptr → ISpTTSEngine vtable     │ ← "this" pointer for ISpTTSEngine
//   │ vtptr → ISpObjectWithToken vtbl │ ← offset "this" for ISpObjectWithToken
//   │ m_refCount                      │
//   │ m_pToken                        │
//   │ m_httpClient                    │
//   │ m_voiceId                       │
//   │ ...                             │
//   └─────────────────────────────────┘
//
//   QueryInterface handles the pointer adjustment between the two vtables.
//   This is standard COM "diamond inheritance" — the compiler does most
//   of the work, but we need to be aware of it for correct QI behavior.
// ============================================================================

#pragma once

#include <windows.h>
#include <sapi.h>
#include <sapiddk.h>
#include <string>

#include "http_client.h"

// Global counters (defined in dllmain.cpp)
extern LONG g_objectCount;

class VoiceLinkEngine : public ISpTTSEngine, public ISpObjectWithToken
{
public:
    VoiceLinkEngine();
    ~VoiceLinkEngine();

    // -----------------------------------------------------------------------
    // IUnknown — The foundation of every COM object
    //
    // Every COM interface inherits from IUnknown. These three methods are
    // how COM manages object lifetime and interface discovery.
    // -----------------------------------------------------------------------

    // "Do you support interface X?" Returns S_OK + pointer if yes.
    // This is how COM does runtime type checking (like dynamic_cast).
    STDMETHODIMP QueryInterface(REFIID riid, void **ppv) override;

    // "I need a reference to you." Increments the reference count.
    // Thread-safe via InterlockedIncrement.
    STDMETHODIMP_(ULONG)
    AddRef() override;

    // "I'm done with you." Decrements the reference count.
    // When it hits 0, the object deletes itself.
    STDMETHODIMP_(ULONG)
    Release() override;

    // -----------------------------------------------------------------------
    // ISpTTSEngine — The actual TTS engine interface
    //
    // SAPI calls these methods to make us speak.
    // -----------------------------------------------------------------------

    // THE BIG ONE. SAPI calls this when an app wants text spoken.
    //
    // Parameters:
    //   dwSpeakFlags    — Bitfield: SPF_ASYNC, SPF_PURGEBEFORESPEAK, etc.
    //   rguidFormatId   — Requested audio format GUID (usually SPDFID_WaveFormatEx)
    //   pWaveFormatEx   — Requested audio format details (can be null)
    //   pTextFragList   — Linked list of text fragments to speak
    //   pOutputSite     — Where we write audio data back to SAPI
    //
    // This method:
    //   1. Extracts text from the fragment list
    //   2. Sends it to the Python inference server via HTTP
    //   3. Streams the PCM audio back through pOutputSite->Write()
    //   4. Checks for abort between chunks
    STDMETHODIMP Speak(
        DWORD dwSpeakFlags,
        REFGUID rguidFormatId,
        const WAVEFORMATEX *pWaveFormatEx,
        const SPVTEXTFRAG *pTextFragList,
        ISpTTSEngineSite *pOutputSite) override;

    // Tell SAPI what audio format we produce.
    //
    // We always produce: 24kHz, 16-bit, mono PCM
    // This matches Kokoro's native output format, so no resampling needed.
    //
    // SAPI calls this before Speak() to set up its audio pipeline.
    // We must allocate the WAVEFORMATEX with CoTaskMemAlloc because
    // SAPI will free it with CoTaskMemFree.
    STDMETHODIMP GetOutputFormat(
        const GUID *pTargetFmtId,
        const WAVEFORMATEX *pTargetWaveFormatEx,
        GUID *pDesiredFmtId,
        WAVEFORMATEX **ppCoMemDesiredWaveFormatEx) override;

    // -----------------------------------------------------------------------
    // ISpObjectWithToken — Links this engine to its registry token
    //
    // Each voice (Kokoro Heart, Kokoro Adam, etc.) has a registry token.
    // When SAPI creates our engine for a specific voice, it calls
    // SetObjectToken so we know WHICH voice we should be.
    // -----------------------------------------------------------------------

    // SAPI tells us which voice token we were created for.
    // We read custom attributes from the token:
    //   - VoiceLinkVoiceId: "af_heart", "am_adam", etc.
    //   - VoiceLinkServerPort: "7860" (optional, defaults to 7860)
    STDMETHODIMP SetObjectToken(ISpObjectToken *pToken) override;

    // SAPI asks which token we're associated with.
    STDMETHODIMP GetObjectToken(ISpObjectToken **ppToken) override;

private:
    // -----------------------------------------------------------------------
    // Private Helpers
    // -----------------------------------------------------------------------

    // Walk the SPVTEXTFRAG linked list and extract all speakable text.
    // Handles SPVA_Speak fragments, skips bookmarks/silence/etc.
    // Also captures the max RateAdj across fragments via pMaxRateAdj output.
    std::string ExtractText(const SPVTEXTFRAG *pTextFragList, LONG *pMaxRateAdj = nullptr);

    // Read a string attribute from our voice token's registry entry.
    std::wstring ReadTokenAttribute(const wchar_t *attrName);

    // -----------------------------------------------------------------------
    // Member Variables
    // -----------------------------------------------------------------------

    LONG m_refCount;            // COM reference count (InterlockedIncrement/Decrement)
    ISpObjectToken *m_pToken;   // Our voice token (AddRef'd, released in destructor)
    TtsHttpClient m_httpClient; // HTTP connection to the inference server
    std::string m_voiceId;      // Voice ID from token ("af_heart", "qwen3_Chelsie", etc.)
    std::string m_model;        // Model backend: "kokoro" (default) or "qwen3"
    INTERNET_PORT m_serverPort; // Server port from token (default: 7860)
    bool m_initialized;         // Have we been fully set up via SetObjectToken?
};

#!/usr/bin/env python3
"""
Test script to debug TTS output
"""

import requests
import json

def test_tts():
    url = "http://127.0.0.1:7860/v1/tts"

    # Test data
    data = {
        "text": "Hello world, this is a test of the VoiceLink ONNX server.",
        "voice": "af_heart",
        "speed": 1.0
    }

    try:
        print("Sending TTS request...")
        response = requests.post(url, json=data)

        print(f"Status code: {response.status_code}")
        print(f"Headers: {dict(response.headers)}")

        if response.status_code == 200:
            # Save audio to file
            with open("test_output.wav", "wb") as f:
                f.write(response.content)

            print(f"Audio saved to test_output.wav ({len(response.content)} bytes)")

            # Check if it's valid audio data
            if len(response.content) > 100:
                print("✅ Received audio data")
            else:
                print("❌ Audio data seems too small")
                print(f"Content preview: {response.content[:100]}")
        else:
            print(f"❌ Error: {response.text}")

    except Exception as e:
        print(f"❌ Exception: {e}")

if __name__ == "__main__":
    test_tts()

